export const SEL_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/sel-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSelStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SEL_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
